import { describe, expect, it } from 'vitest'
import { decodeProjectData, parseProjectFile, projectNameFromFile } from './project'

// A project saved by the app before the generator was removed (DATA_VERSION 1).
const V1_FILE = {
  app: 'ifj26-table-maker',
  version: 1,
  ll: { grammar: 'S -> a S | ε', input: 'a a', sim: { step: 4, speed: 2 } },
  prec: {
    terminals: ['+', 'id', '$', '+', ''],
    cells: { '+|id': '<', 'id|+': '>', 'x|y': '?' },
    rules: 'E -> E + E',
    input: 'id + id',
    gen: { levels: '+ -', ids: 'id', parens: '( )' },
  },
  names: { map: 'a=A', ntPrefix: 'N_', tPrefix: 'T_', precPrefix: 'P_' },
  def: { nonterminals: 'S', terminals: 'a', start: ' S ' },
}

// A file exported by the original single-file HTML tool: no version, no definition, no simulation.
const LEGACY_FILE = {
  app: 'ifj26-table-maker',
  ll: { grammar: 'A -> b', input: 'b' },
  prec: { terminals: ['*'], cells: { '*|*': '>' }, rules: '', input: '', gen: { levels: '*', ids: '', parens: '' } },
  names: { map: '' },
}

describe('decodeProjectData', () => {
  it('migrates a v1 document to the current version, dropping the generator and the simulation state', () => {
    expect(decodeProjectData(V1_FILE)).toEqual({
      app: 'ifj26-table-maker',
      version: 2,
      ll: { grammar: 'S -> a S | ε', input: 'a a' },
      prec: { terminals: ['+', 'id'], cells: { '+|id': '<', 'id|+': '>' }, rules: 'E -> E + E', input: 'id + id' },
      names: { map: 'a=A', ntPrefix: 'N_', tPrefix: 'T_', precPrefix: 'P_' },
      def: { nonterminals: 'S', terminals: 'a', start: 'S' },
    })
  })

  it('accepts a file from the original single-file tool (no version, no definition)', () => {
    expect(decodeProjectData(LEGACY_FILE)).toEqual({
      app: 'ifj26-table-maker',
      version: 2,
      ll: { grammar: 'A -> b', input: 'b' },
      prec: { terminals: ['*'], cells: { '*|*': '>' }, rules: '', input: '' },
      names: { map: '', ntPrefix: 'NT_', tPrefix: 'T_', precPrefix: 'PT_' },
      def: { nonterminals: '', terminals: '', start: '' },
    })
  })

  it.each([null, 42, 'text', [], { ll: 'nope', prec: { terminals: 'x', cells: [] } }])('decodes garbage %j to an empty project', (garbage) => {
    expect(decodeProjectData(garbage)).toEqual({
      app: 'ifj26-table-maker',
      version: 2,
      ll: { grammar: '', input: '' },
      prec: { terminals: [], cells: {}, rules: '', input: '' },
      names: { map: '', ntPrefix: 'NT_', tPrefix: 'T_', precPrefix: 'PT_' },
      def: { nonterminals: '', terminals: '', start: '' },
    })
  })

  it('is idempotent on current documents', () => {
    const once = decodeProjectData(V1_FILE)
    expect(decodeProjectData(once)).toEqual(once)
  })
})

describe('parseProjectFile', () => {
  it('parses an exported project file', () => {
    const result = parseProjectFile(JSON.stringify(V1_FILE))
    expect(result).toEqual({ ok: true, data: decodeProjectData(V1_FILE) })
  })

  it('rejects text that is not JSON', () => {
    expect(parseProjectFile('{ not json')).toEqual({ ok: false, error: 'Súbor nie je platný JSON' })
  })

  it.each(['{"app":"something-else"}', '[]', 'null', '"ifj26-table-maker"'])('rejects JSON that is not a Table Maker project: %s', (text) => {
    expect(parseProjectFile(text)).toEqual({ ok: false, error: 'Súbor nie je projekt Table Maker' })
  })

  it('rejects a file saved by a newer version of the app', () => {
    expect(parseProjectFile(JSON.stringify({ ...V1_FILE, version: 99 }))).toEqual({
      ok: false,
      error: 'Súbor pochádza z novšej verzie aplikácie',
    })
  })
})

describe('projectNameFromFile', () => {
  it('drops the .json extension', () => {
    expect(projectNameFromFile('LL gramatika.JSON')).toBe('LL gramatika')
  })

  it('falls back to a default name', () => {
    expect(projectNameFromFile('.json')).toBe('Importovaný projekt')
  })

  it('cuts long file names to the project name limit', () => {
    const name = projectNameFromFile(`${'a'.repeat(200)}.json`)
    expect(name).toBe('a'.repeat(120))
  })
})
